#!/usr/bin/env node
/**
 * Generates src/lib/kicons/targets.ts from src/lib/kicons/bindings.ts.
 *
 * The icon swap patches the lucide components named in the binding table, so it needs a reference to each. A named
 * import per icon keeps lucide tree-shakeable (a `* as Lucide` import would pull in all ~1,500 icons). This script
 * writes that import list; the contract test (e2e/kicons.spec.ts) fails if the generated file drifts from the table.
 *
 *   node scripts/gen-kicon-targets.mjs
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const lucide = require('lucide-react');

const src = readFileSync(join(root, 'src/lib/kicons/bindings.ts'), 'utf8');
const body = src.slice(src.indexOf('= {') + 3, src.lastIndexOf('};'));
const names = [...body.matchAll(/\b([A-Z][A-Za-z0-9]*)\s*:\s*'[a-z0-9-]+'/g)].map((m) => m[1]);

const unique = [...new Set(names)].sort();
const missing = unique.filter((n) => !(n in lucide));
if (missing.length) {
  console.error(`These bindings are not exports of the installed lucide-react: ${missing.join(', ')}`);
  process.exit(1);
}

const out = `// GENERATED by scripts/gen-kicon-targets.mjs from bindings.ts — do not edit by hand.
import {
${unique.map((n) => `  ${n},`).join('\n')}
} from 'lucide-react';

/** The lucide components the icon swap patches, by export name. */
export const TARGETS: Readonly<Record<string, unknown>> = {
${unique.map((n) => `  ${n},`).join('\n')}
};
`;
writeFileSync(join(root, 'src/lib/kicons/targets.ts'), out);
console.log(`wrote src/lib/kicons/targets.ts (${unique.length} icons)`);
